def dividir_sentencas(texto, max_tokens):
    chunks = []
    atual = []
    tokens_atual = 0
    for s in texto.split(". "):
        t = contar_tokens(s)
        if atual and tokens_atual + t > max_tokens:
            chunks.append(". ".join(atual))
            atual = [s]
            tokens_atual = t
        else:
            atual.append(s)
            tokens_atual += t
    if atual:
        chunks.append(". ".join(atual))
    return chunks

def chunk_seguro(texto, tamanho, overlap):
    if overlap >= tamanho:
        raise ValueError("overlap deve ser menor que tamanho")
    palavras = texto.split()
    if not palavras:
        return []
    if len(palavras) <= tamanho:
        return [" ".join(palavras)]
    passo = tamanho - overlap
    chunks = []
    i = 0
    while i < len(palavras):
        chunks.append(" ".join(palavras[i:i + tamanho]))
        if i + tamanho >= len(palavras):
            break
        i += passo
    return chunks

