def chunk_sem_farelo(texto, tamanho):
    palavras = texto.split()
    if not palavras:
        return []
    chunks = []
    for i in range(0, len(palavras), tamanho):
        chunks.append(" ".join(palavras[i:i + tamanho]))
    if len(chunks) > 1 and len(chunks[-1].split()) < tamanho * 0.25:
        chunks[-2] = chunks[-2] + " " + chunks[-1]
        chunks.pop()
    return chunks

