def buscar_sem_duplicatas(consulta, corpus, k, limiar_dup):
    if not corpus:
        return []
    q = embed(consulta)
    ranqueados = [(t, float(np.dot(embed(t), q))) for t in corpus]
    ranqueados.sort(key=lambda p: -p[1])
    escolhidos = []
    for texto, score in ranqueados:
        v = embed(texto)
        duplicata = False
        for jt, _js in escolhidos:
            if float(np.dot(v, embed(jt))) > limiar_dup:
                duplicata = True
                break
        if not duplicata:
            escolhidos.append((texto, score))
        if len(escolhidos) == k:
            break
    return escolhidos

