def executar_todas(cliente, pedido):
    tools = [{
        "type": "function",
        "function": {
            "name": "somar",
            "description": "Soma dois inteiros.",
            "parameters": {
                "type": "object",
                "properties": {"a": {"type": "integer"}, "b": {"type": "integer"}},
                "required": ["a", "b"],
            },
        },
    }]
    resp = cliente.chat.completions.create(
        model="mock-4",
        messages=[{"role": "user", "content": pedido}],
        tools=tools,
    )
    chamadas = resp.choices[0].message.tool_calls
    if not chamadas:
        return []
    resultados = []
    for chamada in chamadas:
        args = json.loads(chamada.function.arguments)
        resultados.append(args["a"] + args["b"])
    return resultados

import json
import re


class CampoFaltando(Exception):
    def __init__(self, campo):
        super().__init__(f"campo obrigatório ausente: {campo}")
        self.campo = campo


def campo_ou_erro(texto, campo):
    m = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", texto, re.DOTALL)
    bruto = m.group(1) if m else texto
    dados = json.loads(bruto)
    if campo not in dados:
        raise CampoFaltando(campo)
    return dados[campo]

